import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const require = createRequire(import.meta.url);
const prettier = require('prettier');
const format = JSON.parse(
  fs.readFileSync(path.join(root, 'package.json'), 'utf8')
).prettier;
const header =
  '// Generated by scripts/generate-icons.mjs. Coverage and legacy names only; image owns SVG resources.\n';
export function generateOutputs(appRoot, outputRoot = root) {
  const entries = JSON.parse(
    fs.readFileSync(path.join(root, 'scripts/native-list-icons.json'), 'utf8')
  );
  const catalog = JSON.parse(
    fs.readFileSync(
      path.join(root, '../react-native-image/resources/icons/manifest.json'),
      'utf8'
    )
  );
  const records = resolveRecords(entries, catalog, appRoot);
  return renderOutputs(records, outputRoot);
}
export function resolveRecords(entries, catalog, appRoot) {
  const names = new Set();
  if (!Array.isArray(entries)) throw new Error('Invalid icon manifest');
  return entries
    .map((entry) => {
      if (
        !entry ||
        typeof entry.name !== 'string' ||
        !/^[A-Z][A-Za-z0-9]*$/.test(entry.name) ||
        names.has(entry.name) ||
        !Array.isArray(entry.platforms) ||
        !entry.platforms.length ||
        new Set(entry.platforms).size !== entry.platforms.length ||
        entry.platforms.some((p) => !['ios', 'android', 'web'].includes(p)) ||
        !['template', 'original', 'primitive'].includes(entry.rendering)
      )
        throw new Error('Invalid icon manifest entry');
      names.add(entry.name);
      if (entry.name === 'Circle')
        return { ...entry, canonical: 'Circle', width: 24, height: 24 };
      if (
        typeof entry.source !== 'string' ||
        entry.source.includes('..') ||
        path.isAbsolute(entry.source)
      )
        throw new Error('Invalid icon manifest entry');
      const matches = Object.entries(catalog).filter(
        ([, value]) => value.source === entry.source
      );
      if (matches.length > 1)
        throw new Error(`Ambiguous shared SVG source: ${entry.source}`);
      const match = matches[0];
      if (!match) throw new Error(`Missing shared SVG source: ${entry.source}`);
      const [canonical, metadata] = match;
      const source = fs.readFileSync(
        path.join(appRoot, 'packages/components/svg', entry.source),
        'utf8'
      );
      const raw = source.endsWith('\n') ? source : source + '\n';
      if (
        crypto.createHash('sha256').update(raw).digest('hex') !==
        metadata.digest
      )
        throw new Error(`Shared SVG resources stale: ${entry.source}`);
      return {
        ...entry,
        canonical,
        width: metadata.viewBox[2],
        height: metadata.viewBox[3],
      };
    })
    .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
}
function renderOutputs(records, outputRoot) {
  const swift =
    header +
    'import UIKit\n\nstruct NativeListIconMetadata {\n  let name: String\n  let size: CGSize\n  let original: Bool\n}\n\nenum NativeListGeneratedIcons {\n  static let icons: [String: NativeListIconMetadata] = [\n' +
    records
      .filter((x) => x.platforms.includes('ios'))
      .map(
        (x) =>
          `    "${x.name}": NativeListIconMetadata(name: "${
            x.canonical
          }", size: CGSize(width: ${x.width}, height: ${x.height}), original: ${
            x.rendering === 'original'
          }),`
      )
      .join('\n') +
    '\n  ]\n}\n';
  const kotlin =
    header +
    'package com.margelo.nitro.nativelist\n\ninternal data class NativeListIconMetadata(val name: String, val width: Float, val height: Float)\ninternal val nativeListGeneratedIcons: Map<String, NativeListIconMetadata> = mapOf(\n' +
    records
      .filter((x) => x.platforms.includes('android'))
      .map(
        (x) =>
          `  "${x.name}" to NativeListIconMetadata("${x.canonical}", ${x.width}f, ${x.height}f),`
      )
      .join('\n') +
    '\n)\n';
  const web =
    header +
    'export const nativeListGeneratedIcons: Readonly<Record<string, string>> = ' +
    JSON.stringify(
      Object.fromEntries(
        records
          .filter((x) => x.platforms.includes('web'))
          .map((x) => [x.name, x.canonical])
      )
    ) +
    ';\n';
  return new Map([
    [path.join(outputRoot, 'ios/NativeListGeneratedIcons.swift'), swift],
    [
      path.join(
        outputRoot,
        'android/src/main/java/com/onekey/nativelist/NativeListGeneratedIcons.kt'
      ),
      kotlin,
    ],
    [
      path.join(outputRoot, 'src/web/NativeListGeneratedIcons.ts'),
      prettier.format(web, { ...format, parser: 'typescript' }),
    ],
  ]);
}
if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const index = process.argv.indexOf('--app-root');
  if (index < 0 || !process.argv[index + 1])
    throw new Error('Pass --app-root <App checkout>');
  const outputs = generateOutputs(path.resolve(process.argv[index + 1]));
  const stale = [...outputs].filter(
    ([file, text]) =>
      !fs.existsSync(file) || fs.readFileSync(file, 'utf8') !== text
  );
  if (process.argv.includes('--check') && stale.length)
    throw new Error('Stale NativeList icon metadata');
  if (!process.argv.includes('--check'))
    for (const [file, text] of stale) {
      fs.mkdirSync(path.dirname(file), { recursive: true });
      fs.writeFileSync(file, text);
    }
  console.log(JSON.stringify({ outputs: outputs.size, changed: stale.length }));
}
